node -e "
const wordCount = (text) => (text.trim().match(/[A-Za-z]+(?:'[A-Za-z]+)?/g) || []).length;
const est = (w) => Math.round((w/155)*60);

const s1 = \"Cobalt Labs payments platform exits beta with four billion dollars in transaction volume. Cobalt Labs announced general availability of its payments platform after a six-month beta. The company says it processed four billion dollars in volume during beta with partners including Stripe. Top ten stories on HN this week. Weekly digest of trending HN stories. Includes one Cobalt Labs Show HN that hit number one.\";

const s2 = \"Your one o'clock Maya call overlaps with the customer interview at one fifteen. Quick call with Maya. Family call — Mom's birthday planning. free at 1?. Maya wants a quick call at 1pm to lock in Mom's surprise birthday plans for next weekend. Mentions she already booked the restaurant tentatively.\";

const s3 = \"ACTION REQUIRED: credential rotation by May 20. Plaid is requiring all partners to rotate API credentials by 2026-05-20. After that date, unrotated keys will be revoked. Infra is CC'd but Jordan is the listed owner. PSD3 final text dropped overnight — please read before 3pm sync. The EU published the final PSD3 text overnight. Material changes to SCA exemption thresholds and a new fraud-data-sharing requirement that affects our checkout flow. Rahul has annotated the key sections in the linked doc.\";

const s4 = \"EU publishes final PSD3 text; SCA exemption thresholds raised, new fraud-sharing rules. The European Commission released the final PSD3 text overnight. Notable changes include raised strong customer authentication thresholds and a new mandatory fraud-data-sharing scheme among PSPs. Implementation deadline is 2027. Daily Update: The new shape of platform fees in fintech. Long-form analysis of how interchange compression is reshaping platform fee models. Mentions Cobalt Labs and Stripe as examples in the third paragraph.\";

const all = [s1,s2,s3,s4];
let total = 0;
all.forEach((s,i) => { const w = wordCount(s); total += w; console.log('s'+(i+1), w); });
console.log('total', total, 'duration', est(total));
"

