const s1 = \"Cobalt Labs payments platform exits beta with four billion dollars in transaction volume. Cobalt Labs announced general availability of its payments platform after a six-month beta. Top ten stories on HN this week. Includes one Cobalt Labs Show HN that hit number one.\";

const s2 = \"Your one o'clock Maya call overlaps with the customer interview at one fifteen. Quick call with Maya. Family call — Mom's birthday planning. Free at one? Maya wants a quick call at one PM to lock in Mom's surprise birthday plans for next weekend. Mentions she already booked the restaurant tentatively.\";

const s3 = \"ACTION REQUIRED: credential rotation by May twentieth. Plaid is requiring all partners to rotate API credentials by May twentieth, twenty twenty-six. After that date, unrotated keys will be revoked. Infra is CC'd but Jordan is the listed owner.\";

const s4 = \"PSD3 final text dropped overnight — please read before three PM sync. Material changes to SCA exemption thresholds and a new fraud-data-sharing requirement that affects our checkout flow. Rahul has annotated the key sections in the linked doc. The European Commission released the final PSD3 text overnight. Notable changes include raised strong customer authentication thresholds and a new mandatory fraud-data-sharing scheme among PSPs. Implementation deadline is twenty twenty-seven. Daily Update: The new shape of platform fees in fintech. Long-form analysis of how interchange compression is reshaping platform fee models. Mentions Cobalt Labs and Stripe as examples in the third paragraph.\";

const all = [s1,s2,s3,s4];
const joined = all.join('\\n\\n');
let total = 0;
all.forEach((s,i) => {
  const w = wordCount(s);
  total += w;
  console.log('s'+(i+1), 'words', w, 'digits', spokenNumbers(s));
});
console.log('total words', total, 'duration', est(total));
console.log('joined digits', spokenNumbers(joined));
"

